import{_ as r,r as l,o as i,c as s,a as e,b as t,d as n,e as d}from"./chunks/framework.8NMv9ABN.js";const q=JSON.parse('{"title":"Alerts","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/alerts.md","filePath":"uk/tools/alerts.md"}'),c={name:"uk/tools/alerts.md"};function h(u,a,m,p,b,f){const o=l("Screenshot");return i(),s("div",null,[a[0]||(a[0]=e("h1",{id:"alerts",tabindex:"-1"},[t("Alerts "),e("a",{class:"header-anchor",href:"#alerts","aria-label":'Permalink to "Alerts"'},"​")],-1)),a[1]||(a[1]=e("p",null,"Alerts стежить одразу за двома речами й показує їх однією стрічкою:",-1)),a[2]||(a[2]=e("ol",null,[e("li",null,[e("strong",null,"Відхилення цін"),t(" — той самий актив коштує по-різному на різних біржах просто зараз.")]),e("li",null,[e("strong",null,"Нові лістинги"),t(" — токен, який щойно почав торгуватися на доступній біржі.")])],-1)),n(o,{src:"alerts",alt:"Вікно Alerts із картками відхилень і карткою нового лістингу",caption:"Вікно Alerts"}),a[3]||(a[3]=d('<h2 id="як-читати-вікно" tabindex="-1">Як читати вікно <a class="header-anchor" href="#як-читати-вікно" aria-label="Permalink to &quot;Як читати вікно&quot;">​</a></h2><p>Картки впорядковані від найновіших, за часом першої появи. Картка тримає своє місце, поки її числа оновлюються, тож стрічка не перебудовується під вами, поки ви її читаєте.</p><h3 id="картка-відхилення" tabindex="-1">Картка відхилення <a class="header-anchor" href="#картка-відхилення" aria-label="Permalink to &quot;Картка відхилення&quot;">​</a></h3><ul><li><strong>Символ</strong> — клацніть, щоб скопіювати в буфер обміну; на мить покаже <code>Copied!</code>.</li><li><strong>Спред</strong> — живий максимальний розрив цін між біржами у відсотках.</li><li><strong>Легенда</strong> — по одному запису на кожну біржу, де є цей тікер: кольорова крапка, що відповідає його лінії на графіку, назва біржі та її обсяг. Наведення на запис показує точну ціну й обсяг тієї біржі.</li><li><strong>Міні-графік</strong> — по одній ціновій лінії на біржу, щоб було видно, чи розрив розширюється, звужується, чи тримається.</li></ul><h4 id="як-рахується-спред" tabindex="-1">Як рахується спред <a class="header-anchor" href="#як-рахується-спред" aria-label="Permalink to &quot;Як рахується спред&quot;">​</a></h4><p>Відсоток — це <code>(найвища ціна − найнижча ціна) ÷ найнижча ціна × 100</code>, узятий по всіх біржах, які зараз повідомляють цей тікер.</p><p>Ця цифра <strong>жива</strong>. Вона безперервно перераховується з тих самих біржових вебсокетів, що живлять лінії графіка, і оновлюється приблизно двічі на секунду — тобто показує поточний розрив, а не той, що був у момент спрацювання сповіщення.</p><div class="warning custom-block"><p class="custom-block-title">Спред не є гарантованим прибутком</p><p>Це різниця між двома котируваннями. Вона нічого не каже про те, чи змогли б ви на цьому поторгувати: глибина стакана, комісії, фандинг, час переказу й доступність виведення до розрахунку не входять, а видимий розрив може закритися раніше, ніж виконається ордер. Сприймайте це як сигнал подивитися, а не як результат.</p></div><p>Графік навмисно наближений зі щільними ціновими полями, бо розрив між лініями бірж зазвичай малий відносно ціни й у звичайному масштабі був би непомітним.</p><h3 id="картка-нового-лістингу" tabindex="-1">Картка нового лістингу <a class="header-anchor" href="#картка-нового-лістингу" aria-label="Permalink to &quot;Картка нового лістингу&quot;">​</a></h3><p>Картки лістингів виглядають інакше за картки відхилень: тег <strong>NEW</strong>, символ (також із копіюванням по кліку) і час лістингу. Вони ділять стрічку й той самий ліміт карток зі сповіщеннями про відхилення.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Відкрийте вкладку <strong>Alerts</strong> у головному вікні.</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>Скільки карток стрічка показує одночасно. Діапазон <strong>від 3 до 50</strong>, за замовчуванням 9.</p><p>Ліміт застосовується вже після того, як сповіщення про відхилення й лістинги об&#39;єднані та відсортовані, тож обидва типи змагаються за ті самі місця.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Інтервал свічок для цінових ліній усередині карток відхилень. Варіанти: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>. За замовчуванням <code>1m</code>.</p><p>Це змінює лише графік. На розрахунок спреду й на те, які сповіщення проходять, воно не впливає.</p><h3 id="alert-settings" tabindex="-1">Alert settings <a class="header-anchor" href="#alert-settings" aria-label="Permalink to &quot;Alert settings&quot;">​</a></h3><h4 id="minimum-decorrelation" tabindex="-1">Minimum decorrelation <a class="header-anchor" href="#minimum-decorrelation" aria-label="Permalink to &quot;Minimum decorrelation&quot;">​</a></h4><p>Спред, якого тікер має досягти, щоб створити сповіщення. Діапазон <strong>від 1% до 10%</strong> з кроком 0.5%, за замовчуванням 1%.</p><div class="info custom-block"><p class="custom-block-title">Сповіщення не зникають, коли розрив закривається</p><p>Щойно тікер перетнув поріг, він лишається у стрічці й продовжує оновлюватися, навіть якщо його живий спред згодом опуститься нижче мінімуму. Поріг керує тим, що <em>потрапляє</em> всередину, а не тим, що лишається.</p></div><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="alert-sound" tabindex="-1">Alert sound <a class="header-anchor" href="#alert-sound" aria-label="Permalink to &quot;Alert sound&quot;">​</a></h4><p>Відтворює звук при появі нового сповіщення про відхилення. За замовчуванням увімкнено.</p><h4 id="listing-alert-sound" tabindex="-1">Listing alert sound <a class="header-anchor" href="#listing-alert-sound" aria-label="Permalink to &quot;Listing alert sound&quot;">​</a></h4><p>Відтворює звук, коли залістовано новий токен. За замовчуванням увімкнено.</p><p>Обидва незалежні — можна лишити лістинги зі звуком, а відхилення беззвучними, або навпаки.</p><h3 id="volume-filter" tabindex="-1">Volume filter <a class="header-anchor" href="#volume-filter" aria-label="Permalink to &quot;Volume filter&quot;">​</a></h3><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Фільтрує сповіщення про відхилення за обсягом торгів. За замовчуванням вимкнено.</p><div class="info custom-block"><p class="custom-block-title">Потрібні двоє</p><p>Щоб сповіщення про відхилення пройшло фільтр, <strong>щонайменше дві біржі</strong> мають перевищувати мінімальний обсяг. Це зроблено навмисно: ціновий розрив має сенс лише тоді, коли за обома його сторонами стоять реальні торги.</p></div><p>Цей фільтр діє тільки на сповіщення про відхилення. Сповіщення про нові лістинги за обсягом не фільтруються — щойно залістований токен не має значущої історії обсягів.</p><h4 id="minimum-volume" tabindex="-1">Minimum volume <a class="header-anchor" href="#minimum-volume" aria-label="Permalink to &quot;Minimum volume&quot;">​</a></h4><p>5-хвилинний обсяг у доларах, потрібний біржі, щоб її сторона відхилення зараховувалась. Діапазон <strong>від $10K до $1M</strong> з кроком $10K, за замовчуванням $10K.</p><p>Неактивний, поки не увімкнено фільтр обсягу.</p><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/tools/knives.html">Knives</a> — рухи цін на одній біржі замість розривів між біржами. Knives також показує значок <strong>NEW</strong> для свіжих лістингів на своїх картках тікерів.</li><li><a href="/manual/uk/tools/monitor.html">Monitor</a> — ранжований огляд ринку</li></ul>',40))])}const k=r(c,[["render",h]]);export{q as __pageData,k as default};
